"""Pydantic schemas for the Channels & Deploy API (Universal Agent)."""

from __future__ import annotations

import uuid
from datetime import datetime
from typing import Any, Optional

from pydantic import BaseModel, ConfigDict, Field


class OneTimeSecret(BaseModel):
    """A secret generated by the server. Shown once; the API never returns it again."""

    name: str
    value: str
    shown_once: bool = True


class ChannelRead(BaseModel):
    channel: str
    label: str
    description: str
    icon: str
    enabled: bool
    status: str
    embeddable: bool
    phone_number: Optional[str] = None
    provider: Optional[str] = None
    # Non-secret settings only (for example phone_number_id). Secrets never appear here.
    configuration: dict[str, str] = Field(default_factory=dict)
    # Display-only forms of stored secrets, for example {"sdk_secret": "••••a1b2"}.
    masked_secrets: dict[str, str] = Field(default_factory=dict)
    # Present only in the response that generated the secret.
    one_time_secret: Optional[OneTimeSecret] = None


class ChannelsResponse(BaseModel):
    agent_id: uuid.UUID
    agent_name: str
    items: list[ChannelRead]


class ChannelSettingsUpdate(BaseModel):
    """User-settable channel fields. Each channel accepts only its own fields."""

    model_config = ConfigDict(extra="forbid")

    phone_number_id: Optional[str] = Field(default=None, max_length=64)
    instagram_account_id: Optional[str] = Field(default=None, max_length=64)
    phone_number: Optional[str] = Field(default=None, max_length=32)
    inbound_address: Optional[str] = Field(default=None, max_length=254)


class ChannelUpdate(BaseModel):
    """PATCH body. Secrets and tokens are not accepted here; the server generates them."""

    model_config = ConfigDict(extra="forbid")

    enabled: Optional[bool] = None
    status: Optional[str] = None
    provider: Optional[str] = Field(default=None, max_length=40)
    settings: Optional[ChannelSettingsUpdate] = None


class SecretRotation(BaseModel):
    channel: str
    secret_name: str
    secret: str
    masked: str
    shown_once: bool = True


class SnippetSet(BaseModel):
    one_line: str
    sdk: str
    npm_install: str
    npm_import: str


class SdkMethod(BaseModel):
    name: str
    description: str


class InstallGuide(BaseModel):
    platform: str
    label: str
    language: str
    code: str


class TriggerSnippet(BaseModel):
    name: str
    language: str
    code: str


class Verification(BaseModel):
    installed: bool
    events_count: int
    loads_count: int
    last_seen: Optional[datetime] = None


class DeployInfo(BaseModel):
    agent_id: uuid.UUID
    agent_name: str
    public_key: str
    widget_id: uuid.UUID
    widget_status: str
    deploy_status: str
    cdn_base: str
    api_base: str
    snippets: SnippetSet
    sdk_methods: list[SdkMethod]
    install_guides: list[InstallGuide]
    trigger_snippets: list[TriggerSnippet]
    domains: list[str]
    verification: Verification
    theme: dict[str, Any] = Field(default_factory=dict)
    settings: dict[str, Any] = Field(default_factory=dict)


class DomainsUpdate(BaseModel):
    domains: list[str] = Field(default_factory=list)


class DomainsResponse(BaseModel):
    domains: list[str]


class PublishRequest(BaseModel):
    publish: bool = True
